// Helper function to query local fallback
function queryLocalFallback(lat?: number, lng?: number, zone?: string): FallbackSchool[] {
  if (lat !== undefined && lng !== undefined) {
    // Sort by physical proximity to the coordinates
    return [...FALLBACK_SCHOOLS]
      .sort((a, b) => {
        const distA = Math.sqrt(Math.pow(a.lat - lat, 2) + Math.pow(a.lng - lng, 2));
        const distB = Math.sqrt(Math.pow(b.lat - lat, 2) + Math.pow(b.lng - lng, 2));
        return distA - distB;
      })
      .slice(0, 8);
  } else {
    const query = (zone || "San Justo").trim().toLowerCase();
    // Substring match on zone/subZone/address/name
    const matches = FALLBACK_SCHOOLS.filter(s => 
      s.subZone.toLowerCase().includes(query) || 
      s.name.toLowerCase().includes(query) ||
      s.address.toLowerCase().includes(query)
    );
    if (matches.length > 0) {
      return matches.slice(0, 8);
    }
    // Default to San Justo / Ramos Mejía if no match found
    return FALLBACK_SCHOOLS.filter(s => s.subZone === "San Justo" || s.subZone === "Ramos Mejía").slice(0, 8);
  }
}

