// Intelligent Unstructured Text Parser using Gemini to extract real private schools from any user clipboard paste
app.post("/api/parse-pasted-schools", async (req: express.Request, res: express.Response) => {
  const { text } = req.body;
  if (!text || typeof text !== "string") {
    return res.status(400).json({ success: false, error: "No se proporcionó texto para analizar." });
  }

  // If API Key is missing, parse using simple local heuristics
  if (!process.env.GEMINI_API_KEY) {
    console.log("No GEMINI_API_KEY detected. Using basic regex parser.");
    const parsed: FallbackSchool[] = [];
    const lines = text.split(/\n+/);
    lines.forEach(line => {
      if (line.length > 5 && (line.toLowerCase().includes("colegio") || line.toLowerCase().includes("instituto") || line.toLowerCase().includes("escuela"))) {
        const parts = line.split(/[;,|-]+/);
        const name = parts[0]?.trim() || "Colegio Importado";
        const address = parts[1]?.trim() || "Dirección Desconocida, La Matanza, Buenos Aires";
        parsed.push({
          name,
          address,
          subZone: "San Justo",
          lat: -34.6800 + (Math.random() - 0.5) * 0.05,
          lng: -58.5600 + (Math.random() - 0.5) * 0.05
        });
      }
    });
    return res.json({ success: true, schools: parsed.slice(0, 10), source: "local-parser" });
  }

  try {
    const prompt = `Analice el siguiente texto de texto libre, cartelera, correo o listado web y extraiga TODOS los colegios privados reales (colegios, institutos o escuelas de gestión privada) que se mencionen con sus respectivas direcciones físicas.
Si las coordenadas de latitud/longitud no se especifican explícitamente, calcúlelas/estímelas con la mayor precisión posible basándose en la dirección (todas las escuelas deben ubicarse en la República Argentina, principalmente en la provincia de Buenos Aires o CABA).

Texto a analizar:
"""
${text}
"""

Responda estrictamente en formato JSON utilizando el siguiente esquema: un array de objetos, donde cada objeto contiene:
- name (string: nombre del colegio)
- address (string: dirección real completa, ej: Av. de Mayo 1902, Ramos Mejía)
- subZone (string: localidad o subzona, ej: Ramos Mejía, San Justo, Morón, Belgrano, etc.)
- lat (number: latitud aproximada)
- lng (number: longitud aproximada)

Retorne EXCLUSIVAMENTE el array JSON válido, sin explicaciones ni formato markdown adicional.`;

    const response = await ai.models.generateContent({
      model: "gemini-3.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              address: { type: Type.STRING },
              subZone: { type: Type.STRING },
              lat: { type: Type.NUMBER },
              lng: { type: Type.NUMBER }
            },
            required: ["name", "address", "subZone", "lat", "lng"]
          }
        }
      }
    });

    const parsedSchools = JSON.parse(response.text || "[]");
    res.json({ success: true, schools: parsedSchools, source: "gemini-parser" });
  } catch (error: any) {
    console.error("Error parsing pasted text with Gemini:", error);
    res.status(500).json({ success: false, error: "No se pudo interpretar el texto ingresado. Verifique el formato e intente nuevamente." });
  }
});

